import {COLORS,uid,dateKey,tasksFor,progress,stats,validateState,seedState,createProject,createTask,toggleTask,removeProject} from './core.js';
const KEY='karsa.workspace.v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/><path d="M3 10h18"/>',check:'<path d="m8 12 3 3 7-8"/><rect x="3" y="3" width="18" height="18" rx="4"/>',checkCircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',chevron:'<path d="m9 6 6 6-6 6"/>',down:'<path d="m7 10 5 5 5-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',settings:'<path d="m9 3-.7 3-2.8 1L3 5.8 1.5 8.5 4 10.8V14l-2.5 1.8 1.5 2.8L6 18l2.2 1.5.8 3h3l.8-3 2.7-1 2.5 1.2 1.5-2.7-2.5-2.3v-3.2l2.5-1.8L18 6.9l-3 .6L12.8 6 12 3z" transform="translate(1 -1) scale(.95)"/><circle cx="11.5" cy="11.5" r="3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',leaf:'<path d="M20 3C7 2 2 8 5 15s15 8 15-12Z"/><path d="M4 21 16 8"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m14 4 6 6M4 20l5-1L21 7l-5-5L4 14z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.folder}</svg>`;
const brandMark='<span class="brand-mark"><svg viewBox="0 0 38 38" fill="none" aria-hidden="true"><path d="M9 6v26m3-14L29 6M12 18l18 14" stroke="currentColor" stroke-width="4.6" stroke-linecap="round"/><path d="m19 15 6 4" stroke="#a9bd84" stroke-width="4.6" stroke-linecap="round"/></svg></span>';
const ps={active:'Aktif',paused:'Dijeda',done:'Selesai'},ts={todo:'Belum mulai',doing:'Dikerjakan',done:'Selesai'},pr={low:'Rendah',medium:'Sedang',high:'Tinggi'};
let recovery=false;
let state;
try{const raw=localStorage.getItem(KEY);state=raw?validateState(JSON.parse(raw)):seedState();}catch{state=seedState();recovery=true;}
let projectFilter='active',taskFilter='open',projectQuery='',taskQuery='',taskProject='',projectView='grid',detailFilter='all',openTaskId=null,toastTimer;
function save(message){try{localStorage.setItem(KEY,JSON.stringify(state));if(message)toast(message);return true;}catch{toast('Penyimpanan browser penuh atau diblokir. Ekspor cadangan sebelum menutup halaman.');return false;}}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
function route(){const parts=location.hash.slice(1).split('/');return {page:['projects','tasks','completed','project'].includes(parts[0])?parts[0]:'overview',id:parts[1]||''};}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function dateLabel(date,short=false){if(!date)return 'Tanpa tenggat';const d=new Date(`${date}T12:00:00`);if(Number.isNaN(d.getTime()))return 'Tanpa tenggat';return d.toLocaleDateString('id-ID',{day:'numeric',month:short?'short':'long'});}
function relativeDate(date){if(!date)return '';if(date===dateKey())return 'Hari ini';if(date===dateKey(1))return 'Besok';return dateLabel(date,true);}
function projectIcon(p){return p.id==='portfolio'?'code':p.id==='desk'?'sun':p.id==='morning'?'leaf':'folder';}
function empty(title,text,action='',label=''){return `<div class="empty">${icon('leaf')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action?`<button class="btn primary" data-action="${action}">${icon('plus')}${esc(label)}</button>`:''}</div>`;}
function render(){
 const {page,id}=route(),s=stats(state),p=state.projects.find(p=>p.id===id);const activePage=page==='project'?'projects':page;
 const nav=[['overview','home','Ringkasan'],['projects','folder','Proyek'],['tasks','check','Tugas'],['completed','checkCircle','Selesai']];
 const navHtml=nav.map(([key,ic,label])=>`<a href="#${key}" class="${activePage===key?'active':''}" ${activePage===key?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${key==='tasks'&&s.open?`<span class="nav-count">${s.open}</span>`:''}</a>`).join('');
 const names={overview:'Ringkasan',projects:'Proyek',tasks:'Tugas',completed:'Selesai',project:p?.name||'Proyek'};
 const focused=document.activeElement?.dataset?.filter;const sel=document.activeElement?.selectionStart;const focusTask=document.activeElement?.dataset?.toggleTask;
 $('#app').innerHTML=`<aside class="sidebar"><a href="#overview" class="brand" aria-label="Karsa beranda">${brandMark}karsa<span class="brand-dot">.</span></a><div class="workspace-switch"><div class="avatar">P</div><div><strong>Workspace pribadi</strong><small>Ruang untuk bertumbuh</small></div>${icon('down')}</div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Navigasi utama">${navHtml}</nav><div class="side-bottom"><div class="private-note">${icon('lock')}<strong>Hanya untuk kamu.</strong><p>Tempat tenang untuk ide<br>dan rencana besarmu.</p></div><button class="plain" data-action="settings">${icon('settings')}Data & preferensi</button><div class="profile"><div class="avatar">P</div><div><strong>Pongo</strong><small>Personal workspace</small></div>${icon('leaf')}</div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')} <b>${esc(names[page])}</b></div><a class="mobile-brand" href="#overview" aria-label="Karsa beranda">${brandMark}karsa<span class="brand-dot">.</span></a><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Cari proyek atau tugas">${icon('search')}<span>Cari sesuatu…</span><span class="key">⌘ K</span></button><span class="top-private">${icon('lock')} Privat</span></div></header><main id="main" class="main fade" tabindex="-1">${page==='overview'?overview():page==='projects'?projectsPage():page==='tasks'?tasksPage():page==='completed'?completedPage():projectPage(p)}</main></div><nav class="bottom-nav" aria-label="Navigasi seluler">${nav.map(([key,ic,label])=>`<a href="#${key}" class="${activePage===key?'active':''}" ${activePage===key?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}<button data-action="settings">${icon('settings')}Data</button></nav>`;
 if(focused){const el=$(`[data-filter="${focused}"]`);if(el){el.focus();if(el.setSelectionRange&&sel!=null)el.setSelectionRange(sel,sel);}}
 if(focusTask){const el=[...document.querySelectorAll('[data-toggle-task]')].find(el=>el.dataset.toggleTask===focusTask);el?.focus();}
 document.title=`${names[page]} · Karsa`;
}
const footer=()=>`<footer class="page-footer"><span>${state.demo?'<button class="plain demo-label" data-action="settings">Data contoh · mulai dengan rencanamu</button>':`${icon('leaf')} Sedikit demi sedikit, jadi berarti.`}</span><span>${icon('checkCircle')} Tersimpan di browser ini</span></footer>`;
function projectCard(p){const tasks=tasksFor(state,p.id),done=tasks.filter(t=>t.status==='done').length;return `<article class="project-card ${p.color}"><div class="card-top"><div class="project-symbol ${p.color}">${icon(projectIcon(p))}</div><div class="card-title"><h3><a href="#project/${esc(p.id)}">${esc(p.name)}</a></h3><p>${esc(p.description||'Satu ide. Banyak kemungkinan.')}</p></div><span class="pill ${p.status}">${ps[p.status]}</span></div><div class="card-progress"><div class="progress-caption"><span>${done} dari ${tasks.length} tugas selesai</span><b>${progress(state,p.id)}%</b></div><div class="progress-track" role="progressbar" aria-label="Progres ${esc(p.name)}" aria-valuenow="${progress(state,p.id)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${progress(state,p.id)}%"></div></div></div><div class="card-bottom"><span class="card-meta">${icon('calendar')}${dateLabel(p.due,true)}</span><a href="#project/${esc(p.id)}" class="plain continue" aria-label="Lanjutkan ${esc(p.name)}">Lanjutkan ${icon('arrow')}</a></div></article>`;}
function taskRow(t,full=false){const p=state.projects.find(p=>p.id===t.projectId),checks=t.checklist.filter(c=>c.done).length;return `<div class="task-row ${t.status==='done'?'completed':''}"><input class="task-check" type="checkbox" ${t.status==='done'?'checked':''} data-toggle-task="${esc(t.id)}" aria-label="${t.status==='done'?'Buka kembali':'Selesaikan'} ${esc(t.title)}"><div class="task-main"><button class="task-title" data-task="${esc(t.id)}">${esc(t.title)}</button><div class="task-meta"><span class="task-project-dot ${p?.color||''}"></span><span>${esc(p?.name||'Proyek')}</span>${t.due?`<span>·</span><span class="${t.due<dateKey()&&t.status!=='done'?'overdue':''}">${relativeDate(t.due)}</span>`:''}${t.checklist.length?`<span>·</span>${icon('check')}<span>${checks}/${t.checklist.length}</span>`:''}</div></div>${full?`<span class="task-status ${t.status}">${ts[t.status]}</span>`:''}<span class="priority-mark ${t.priority}" title="Prioritas ${pr[t.priority]}" aria-label="Prioritas ${pr[t.priority]}"></span>${full?`<button class="icon-btn" data-task="${esc(t.id)}" aria-label="Detail ${esc(t.title)}">${icon('chevron')}</button>`:''}</div>`;}
function overview(){const s=stats(state),active=state.projects.filter(p=>p.status==='active');const upcoming=state.tasks.filter(t=>t.status!=='done'&&state.projects.some(p=>p.id===t.projectId&&p.status==='active')).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4);const date=new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 return `<div class="page-head"><div><div class="eyebrow"><span class="dot"></span>${esc(date)}</div><h1>Ruang untuk <em>berkarya.</em></h1><p class="subtitle">Atur rencana, ambil satu langkah, dan buat kemajuan.</p></div><button class="btn primary" data-action="new-project">${icon('plus')}Proyek baru</button></div><section class="welcome" aria-label="Selamat datang"><div class="welcome-copy"><div class="eyebrow">RENCANA KECIL. KEMUNGKINAN BESAR.</div><h2>Ide baik dimulai<br>dari langkah kecil.</h2><p>Kamu tidak harus menyelesaikan semuanya hari ini.</p><a class="plain" href="#tasks">Pilih langkah berikutnya ${icon('arrow')}</a></div><div class="welcome-art" aria-hidden="true"><div class="art-circle"></div><div class="art-circle two"></div><div class="art-circle three"></div><div class="art-spark">✧</div><div class="art-flower"><svg viewBox="0 0 100 100" fill="none"><path d="M50 49C10 36 20 2 43 16c4-29 34-18 25 9 29-14 46 11 17 26 29 16 7 40-16 23 8 29-23 38-28 11-23 20-43-8-15-24C-3 56 6 26 50 49Z" stroke="currentColor" stroke-width="1.2"/><circle cx="51" cy="53" r="10" fill="#a6bb82"/><path d="M52 64v35" stroke="currentColor"/></svg></div></div></section><section class="stats" aria-label="Statistik workspace">${[[s.active,'Proyek aktif','folder','Sedang kamu kerjakan'],[s.open,'Tugas terbuka','check','Satu langkah setiap hari'],[s.done,'Tugas selesai','checkCircle','Kemajuan yang berarti']].map(([n,label,ic,hint])=>`<div class="stat"><div class="stat-symbol">${icon(ic)}</div><div><span class="stat-label">${label}</span><div class="stat-content"><b class="stat-number">${String(n).padStart(2,'0')}</b><span class="stat-hint">${hint}</span></div></div></div>`).join('')}</section><div class="dashboard-grid"><section><div class="section-title"><h2>Proyek aktif <span class="section-count">${active.length}</span></h2><a href="#projects" class="plain">Semua proyek ${icon('arrow')}</a></div><div class="project-stack">${active.length?active.slice(0,3).map(projectCard).join(''):empty('Ruang untuk ide berikutnya','Mulai proyek pertamamu. Tugas bisa kamu tambah satu per satu.','new-project','Buat proyek')}</div></section><aside><div class="section-title"><h2>Langkah berikutnya</h2><button class="plain" data-action="new-task">${icon('plus')}Tugas</button></div><div class="task-panel"><div class="task-panel-label"><span>TERDEKAT UNTUK KAMU</span>${icon('clock')}</div>${upcoming.length?upcoming.map(t=>taskRow(t)).join(''):empty('Semua terasa lebih ringan','Belum ada tugas terbuka di proyek aktif.')}<div class="task-panel-bottom"><a href="#tasks" class="plain">Lihat semua tugas ${icon('arrow')}</a></div></div><div class="note-card">${icon('spark')}<div class="eyebrow">PENGINGAT KECIL</div><p>Pelan juga tetap<br>sebuah perjalanan.</p><small>Yang penting, terus bergerak.</small></div></aside></div>${footer()}`;
}
function projectsPage(){const filtered=state.projects.filter(p=>(projectFilter==='all'||p.status===projectFilter)&&`${p.name} ${p.description}`.toLowerCase().includes(projectQuery.toLowerCase()));return `<div class="page-head"><div><div class="eyebrow">DARI IDE MENJADI NYATA</div><h1>Proyek <em>kamu.</em></h1><p class="subtitle">Setiap hal besar punya tempat untuk dimulai.</p></div><button class="btn primary" data-action="new-project">${icon('plus')}Proyek baru</button></div><div class="toolbar"><div class="tabs" aria-label="Filter proyek">${[['active','Aktif'],['paused','Dijeda'],['done','Selesai'],['all','Semua']].map(([v,l])=>`<button class="tab ${projectFilter===v?'active':''}" data-project-filter="${v}" aria-pressed="${projectFilter===v}">${l}<b>${state.projects.filter(p=>v==='all'||p.status===v).length}</b></button>`).join('')}</div><div class="filter-tools"><div class="filter-input">${icon('search')}<input aria-label="Cari proyek" data-filter="project-query" placeholder="Cari proyek…" value="${esc(projectQuery)}"></div><div class="view-toggle"><button class="icon-btn ${projectView==='grid'?'active':''}" data-view="grid" aria-label="Tampilan kartu" aria-pressed="${projectView==='grid'}">${icon('grid')}</button><button class="icon-btn ${projectView==='list'?'active':''}" data-view="list" aria-label="Tampilan daftar" aria-pressed="${projectView==='list'}">${icon('list')}</button></div></div></div><div class="project-${projectView}">${filtered.map(projectCard).join('')}${!filtered.length?empty('Belum ada proyek di sini',projectQuery?'Coba nama atau kata kunci yang lain.':'Setiap ide punya waktunya. Buat proyek saat kamu siap.') :''}${!projectQuery?`<button class="new-project-tile" data-action="new-project">${icon('plus')}Beri ruang untuk ide baru</button>`:''}</div>${footer()}`;}
function filterTasks(tasks,filter){return tasks.filter(t=>filter==='all'||(filter==='open'?t.status!=='done':t.status===filter));}
function tasksPage(){let list=filterTasks(state.tasks,taskFilter).filter(t=>(!taskProject||t.projectId===taskProject)&&t.title.toLowerCase().includes(taskQuery.toLowerCase()));list.sort((a,b)=>(a.status==='done')-(b.status==='done')||(a.due||'9999').localeCompare(b.due||'9999'));return `<div class="page-head"><div><div class="eyebrow">SEDIKIT DEMI SEDIKIT</div><h1>Satu tugas, <em>satu langkah.</em></h1><p class="subtitle">Buat tugas sendiri, pecah jadi checklist, lalu mulai.</p></div><button class="btn primary" data-action="new-task">${icon('plus')}Tugas baru</button></div><div class="toolbar"><div class="tabs" aria-label="Filter tugas">${[['open','Terbuka'],['doing','Dikerjakan'],['done','Selesai'],['all','Semua']].map(([v,l])=>`<button class="tab ${taskFilter===v?'active':''}" data-task-filter="${v}" aria-pressed="${taskFilter===v}">${l}<b>${filterTasks(state.tasks,v).length}</b></button>`).join('')}</div><div class="filter-tools"><div class="filter-input">${icon('search')}<input aria-label="Cari tugas" data-filter="task-query" placeholder="Cari tugas…" value="${esc(taskQuery)}"></div><select class="tasks-filter" aria-label="Filter berdasarkan proyek" data-filter="task-project"><option value="">Semua proyek</option>${state.projects.map(p=>`<option value="${esc(p.id)}" ${taskProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><section class="task-panel tasks-page"><div class="task-list-header"><span>${list.length} tugas ${taskFilter==='open'?'terbuka':''}</span><span>Diurutkan berdasarkan tenggat</span></div>${list.length?list.map(t=>taskRow(t,true)).join(''):empty('Tidak ada tugas di sini',taskQuery||taskProject?'Coba ubah pencarian atau filter proyek.':'Tambahkan langkah kecil berikutnya.','new-task','Buat tugas')}</section>${footer()}`;}
function completedPage(){const projects=state.projects.filter(p=>p.status==='done'),tasks=state.tasks.filter(t=>t.status==='done');return `<div class="page-head"><div><div class="eyebrow">APRESIASI SETIAP KEMAJUAN</div><h1>Sudah <em>jadi.</em></h1><p class="subtitle">Lihat kembali hal-hal yang berhasil kamu selesaikan.</p></div></div><div class="section-title"><h2>Proyek selesai <span class="section-count">${projects.length}</span></h2></div><section class="project-grid">${projects.length?projects.map(projectCard).join(''):empty('Perjalananmu sedang berjalan','Proyek yang ditandai selesai akan muncul di sini.')}</section><section style="margin-top:30px"><div class="section-title"><h2>Tugas selesai <span class="section-count">${tasks.length}</span></h2></div><div class="task-panel tasks-page">${tasks.length?tasks.map(t=>taskRow(t,true)).join(''):empty('Langkah kecilmu akan tercatat','Tandai tugas selesai untuk melihat kemajuan di sini.')}</div></section>${footer()}`;}
function projectPage(p){if(!p)return `<a href="#projects" class="detail-back">${icon('back')}Kembali ke proyek</a>${empty('Proyek tidak ditemukan','Proyek mungkin sudah dihapus. Kembali ke daftar untuk memilih proyek lain.')}`;const tasks=tasksFor(state,p.id),list=filterTasks(tasks,detailFilter),done=tasks.filter(t=>t.status==='done').length;return `<a href="#projects" class="detail-back">${icon('back')}Semua proyek</a><div class="detail-head"><div class="project-symbol ${p.color}">${icon(projectIcon(p))}</div><div><div class="eyebrow">PROYEK PRIBADI</div><h1>${esc(p.name)}</h1><p class="subtitle">${esc(p.description||'Satu ide. Banyak kemungkinan.')}</p></div></div><div class="detail-layout"><section>${p.status==='done'?'<div class="status-notice">Proyek ini sudah ditandai selesai. Kamu bisa mengaktifkannya kembali lewat status proyek.</div>':''}<div class="section-title"><h2>Tugas proyek <span class="section-count">${tasks.length}</span></h2><button class="btn primary small" data-action="new-task" data-project="${esc(p.id)}">${icon('plus')}Tambah tugas</button></div><div class="tabs" style="margin-bottom:16px">${[['all','Semua'],['open','Terbuka'],['done','Selesai']].map(([v,l])=>`<button class="tab ${detailFilter===v?'active':''}" data-detail-filter="${v}" aria-pressed="${detailFilter===v}">${l} <b>${filterTasks(tasks,v).length}</b></button>`).join('')}</div><div class="task-panel tasks-page">${list.length?list.map(t=>taskRow(t,true)).join(''):empty(tasks.length?'Belum ada tugas dengan status ini':'Mulai dengan satu tugas',tasks.length?'Ubah filter untuk melihat tugas lainnya.':'Tugas tidak dibuat otomatis. Tentukan langkah pertamamu.','new-task','Tambah tugas')}</div></section><aside class="detail-info"><h3>Tentang proyek</h3><div class="info-row"><span>Status</span><select aria-label="Status proyek" data-project-status="${esc(p.id)}">${Object.entries(ps).map(([v,l])=>`<option value="${v}" ${p.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="info-row"><span>Tenggat</span><span>${dateLabel(p.due,true)}</span></div><div class="detail-progress ${p.color}"><div class="progress-caption"><span>Progres keseluruhan</span><b>${progress(state,p.id)}%</b></div><div class="progress-track" role="progressbar" aria-label="Progres proyek" aria-valuenow="${progress(state,p.id)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${progress(state,p.id)}%"></div></div><p class="helper" style="margin:10px 0 0">${done} dari ${tasks.length} tugas selesai</p></div><button class="btn" data-edit-project="${esc(p.id)}">${icon('edit')}Edit proyek</button><p class="detail-info-note">Progres mengikuti tugas yang kamu tandai selesai. Checklist membantu memecah langkahnya.</p></aside></div>${footer()}`;}
function showDialog(selector,html){const d=$(selector);d.innerHTML=html;if(!d.open)d.showModal();}
const modalHead=(title,eyebrow='RUANG UNTUK RENCANA')=>`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><button class="icon-btn" data-close aria-label="Tutup">${icon('close')}</button></div>`;
function projectForm(id){const p=state.projects.find(p=>p.id===id);showDialog('#form-dialog',`${modalHead(p?'Edit proyek':'Beri ruang untuk ide baru.')}<form class="modal-body" id="project-form" data-id="${esc(id||'')}"><div class="field"><label for="project-name">Nama proyek</label><input id="project-name" name="name" required maxlength="120" value="${esc(p?.name||'')}" placeholder="Apa yang ingin kamu wujudkan?" autofocus></div><div class="field"><label for="project-description">Deskripsi <small>· opsional</small></label><textarea id="project-description" name="description" maxlength="2000" placeholder="Sedikit cerita tentang proyek ini…">${esc(p?.description||'')}</textarea></div><div class="field-row"><div class="field"><label for="project-due">Tenggat <small>· opsional</small></label><input type="date" id="project-due" name="due" value="${esc(p?.due||'')}"></div><div class="field"><label for="project-status">Status</label><select id="project-status" name="status">${Object.entries(ps).map(([v,l])=>`<option value="${v}" ${p?.status===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field"><label>Warna proyek</label><div class="swatches">${COLORS.map(c=>`<label class="swatch ${c}" title="${c}"><input type="radio" name="color" value="${c}" aria-label="Warna ${c}" ${(p?.color||'sage')===c?'checked':''}>${icon('folder')}</label>`).join('')}</div></div><p class="helper">Tambahkan tugas secara manual setelah proyek dibuat.</p><div class="form-error" role="alert"></div><div class="form-actions">${p?`<button type="button" class="plain danger-text" data-delete-project="${esc(p.id)}" style="margin-right:auto">${icon('trash')}Hapus</button>`:''}<button type="button" class="btn" data-close>Batal</button><button class="btn primary" type="submit">${p?'Simpan perubahan':'Buat proyek'}${icon('arrow')}</button></div></form>`);}
function checkField(c={}){return `<div class="form-check" data-check-id="${esc(c.id||'')}" data-done="${c.done?'true':'false'}"><input name="checktext" maxlength="300" value="${esc(c.text||'')}" placeholder="Langkah kecil berikutnya…" aria-label="Item checklist"><button type="button" class="icon-btn" data-remove-check aria-label="Hapus item checklist">${icon('close')}</button></div>`;}
function taskForm(projectId,id){const t=state.tasks.find(t=>t.id===id);if(!state.projects.length){projectForm();toast('Buat proyek dulu untuk menambahkan tugas.');return;}const current=route();const selected=t?.projectId||projectId||(current.page==='project'?current.id:'');showDialog('#form-dialog',`${modalHead(t?'Edit tugas':'Satu langkah berikutnya.','BUAT SECARA MANUAL')}<form class="modal-body" id="task-form" data-id="${esc(id||'')}"><div class="field"><label for="task-title">Nama tugas</label><input id="task-title" name="title" required maxlength="200" value="${esc(t?.title||'')}" placeholder="Apa yang ingin kamu kerjakan?" autofocus></div><div class="field"><label for="task-project">Proyek</label><select id="task-project" name="projectId" required>${state.projects.map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(p.name)}${p.status==='done'?' · selesai':''}</option>`).join('')}</select></div><div class="field-row"><div class="field"><label for="task-due">Tenggat <small>· opsional</small></label><input type="date" id="task-due" name="due" value="${esc(t?.due||'')}"></div><div class="field"><label for="task-priority">Prioritas</label><select id="task-priority" name="priority">${Object.entries(pr).map(([v,l])=>`<option value="${v}" ${(t?.priority||'medium')===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field"><label for="task-notes">Catatan <small>· opsional</small></label><textarea id="task-notes" name="notes" maxlength="5000" placeholder="Detail yang ingin kamu ingat…">${esc(t?.notes||'')}</textarea></div><div class="field"><label>Checklist <small>· opsional</small></label><div class="form-checks">${(t?.checklist||[]).map(checkField).join('')}</div><button type="button" class="plain" data-add-check style="justify-content:flex-start">${icon('plus')}Tambah langkah</button></div><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-close>Batal</button><button class="btn primary" type="submit">${t?'Simpan perubahan':'Buat tugas'}${icon('arrow')}</button></div></form>`);}
function showTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;openTaskId=id;const p=state.projects.find(p=>p.id===t.projectId),n=t.checklist.filter(c=>c.done).length;showDialog('#task-dialog',`${modalHead('Detail tugas','SATU LANGKAH LEBIH DEKAT')}<div class="modal-body"><a class="task-detail-project" href="#project/${esc(p.id)}" data-close>${icon('folder')}${esc(p.name)}${icon('chevron')}</a><h3 class="task-detail-title">${esc(t.title)}</h3><div class="task-detail-controls"><label>Status tugas<select aria-label="Status tugas" data-task-status="${esc(t.id)}">${Object.entries(ts).map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Prioritas<select aria-label="Prioritas tugas" data-task-priority="${esc(t.id)}">${Object.entries(pr).map(([v,l])=>`<option value="${v}" ${t.priority===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="task-meta">${icon('calendar')} ${t.due?`Tenggat ${dateLabel(t.due)}`:'Belum ada tenggat'}</p>${t.notes?`<p class="task-notes">${esc(t.notes)}</p>`:''}<div class="task-checklist-heading"><strong>Checklist</strong><small>${n} dari ${t.checklist.length} selesai</small></div><div class="progress-track"><div class="progress-fill" style="width:${t.checklist.length?n/t.checklist.length*100:0}%"></div></div><div class="checklist-items">${t.checklist.map(c=>`<label class="checklist-item"><input type="checkbox" class="task-check" data-check="${esc(c.id)}" data-parent="${esc(t.id)}" ${c.done?'checked':''}><span>${esc(c.text)}</span></label>`).join('')}</div><form class="checklist-add" id="quick-check" data-id="${esc(t.id)}"><input name="text" maxlength="300" placeholder="Tambah langkah kecil…" aria-label="Langkah checklist baru" required><button class="btn small" type="submit" aria-label="Tambah langkah">${icon('plus')}</button></form><p class="helper" style="margin:10px 0 0">Tandai tugas selesai sendiri setelah semua langkah beres.</p><div class="task-detail-footer"><button class="plain danger-text" data-delete-task="${esc(t.id)}">${icon('trash')}Hapus tugas</button><button class="btn" data-edit-task="${esc(t.id)}">${icon('edit')}Edit tugas</button></div></div>`);}
function settings(){showDialog('#settings-dialog',`${modalHead('Workspace kamu.','DATA & PREFERENSI')}<div class="modal-body"><section class="settings-section"><h3>Penyimpanan di perangkat ini</h3><p>Prototipe Karsa menyimpan perubahan di browser ini. Data belum disinkronkan antarperangkat. Ekspor cadangan sebelum pindah browser atau membersihkan data situs.</p><span class="pill">Akses website privat</span></section><section class="settings-section"><h3>Cadangkan rencanamu</h3><p>Unduh seluruh proyek, tugas, dan checklist. Impor cadangan Karsa untuk mengganti data workspace saat ini.</p><button class="btn" data-action="export">${icon('download')}Ekspor data</button><button class="btn" data-action="import">${icon('upload')}Impor cadangan</button><input type="file" id="import-file" accept="application/json,.json" hidden><div id="import-error" class="form-error" role="alert"></div></section><section class="settings-section"><h3>${state.demo?'Kamu sedang memakai data contoh':'Mulai lagi dengan ruang kosong'}</h3><p>${state.demo?'Jelajahi contoh proyek dan tugas, atau kosongkan workspace untuk mulai dengan rencanamu sendiri.':'Kosongkan seluruh proyek dan tugas di browser ini. Simpan cadangan lebih dahulu jika masih diperlukan.'}</p><button class="btn" data-action="clear-workspace">Mulai workspace kosong</button></section></div>`);}
function openSearch(){showDialog('#search-dialog',`<div class="search-box">${icon('search')}<input id="global-search" placeholder="Cari proyek atau tugas…" aria-label="Cari proyek atau tugas" autofocus><button class="icon-btn" data-close aria-label="Tutup pencarian">${icon('close')}</button></div><div class="search-results" id="search-results"><div class="search-hint">Temukan ide, proyek, atau langkah berikutnya.</div></div>`);}
function searchResults(q){q=q.trim().toLowerCase();if(!q){$('#search-results').innerHTML='<div class="search-hint">Ketik nama proyek atau tugas untuk mencari.</div>';return;}const projects=state.projects.filter(p=>`${p.name} ${p.description}`.toLowerCase().includes(q)).slice(0,5),tasks=state.tasks.filter(t=>`${t.title} ${t.notes}`.toLowerCase().includes(q)).slice(0,8);$('#search-results').innerHTML=projects.map(p=>`<a href="#project/${esc(p.id)}" class="search-result" data-close>${icon('folder')}<span><strong>${esc(p.name)}</strong><small>Proyek · ${ps[p.status]}</small></span></a>`).join('')+tasks.map(t=>`<button class="search-result" data-search-task="${esc(t.id)}">${icon('check')}<span><strong>${esc(t.title)}</strong><small>Tugas · ${esc(state.projects.find(p=>p.id===t.projectId)?.name)}</small></span></button>`).join('')||'<div class="search-hint">Belum ketemu. Coba kata kunci yang lain.</div>';}
function refreshTask(){const focusCheck=document.activeElement?.dataset?.check;const focusStatus=document.activeElement?.dataset?.taskStatus;const focusPriority=document.activeElement?.dataset?.taskPriority;render();if($('#task-dialog').open&&openTaskId){showTask(openTaskId);const key=focusCheck?'check':focusStatus?'taskStatus':focusPriority?'taskPriority':null;const value=focusCheck||focusStatus||focusPriority;if(key)[...document.querySelectorAll('#task-dialog input, #task-dialog select')].find(el=>el.dataset[key]===value)?.focus();}}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,a,[data-close]');if(!el)return;
 if(el.hasAttribute('data-close'))el.closest('dialog')?.close();
 if(el.dataset.task){showTask(el.dataset.task);return;}
 if(el.dataset.searchTask){$('#search-dialog').close();showTask(el.dataset.searchTask);return;}
 if(el.dataset.editProject){projectForm(el.dataset.editProject);return;}
 if(el.dataset.editTask){$('#task-dialog').close();taskForm(null,el.dataset.editTask);return;}
 if(el.dataset.projectFilter){projectFilter=el.dataset.projectFilter;render();return;}
 if(el.dataset.taskFilter){taskFilter=el.dataset.taskFilter;render();return;}
 if(el.dataset.detailFilter){detailFilter=el.dataset.detailFilter;render();return;}
 if(el.dataset.view){projectView=el.dataset.view;render();return;}
 if(el.hasAttribute('data-add-check')){if($$('.form-check').length>=100){toast('Maksimal 100 langkah per tugas.');return;}$('.form-checks').insertAdjacentHTML('beforeend',checkField());$('.form-checks').lastElementChild.querySelector('input').focus();return;}
 if(el.hasAttribute('data-remove-check')){el.closest('.form-check').remove();return;}
 if(el.dataset.deleteProject){const p=state.projects.find(p=>p.id===el.dataset.deleteProject);if(confirm(`Hapus proyek “${p.name}” beserta semua tugasnya?`)){removeProject(state,p.id);save('Proyek dihapus.');$('#form-dialog').close();go('#projects');render();}return;}
 if(el.dataset.deleteTask){const t=state.tasks.find(t=>t.id===el.dataset.deleteTask);if(confirm(`Hapus tugas “${t.title}” dan checklist-nya?`)){state.tasks=state.tasks.filter(x=>x.id!==t.id);save('Tugas dihapus.');$('#task-dialog').close();openTaskId=null;render();}return;}
 switch(el.dataset.action){
 case 'new-project':projectForm();break;
 case 'new-task':taskForm(el.dataset.project);break;
 case 'settings':settings();break;
 case 'search':openSearch();break;
 case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`karsa-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Cadangan Karsa diunduh.');break;}
 case 'import':$('#import-file').click();break;
 case 'clear-workspace':if(confirm('Kosongkan seluruh proyek dan tugas di browser ini? Ekspor data dahulu jika masih diperlukan.')){state={version:1,demo:false,projects:[],tasks:[]};save('Ruang baru untuk rencanamu.');$('#settings-dialog').close();projectFilter='active';taskFilter='open';taskProject='';go('#overview');render();}break;
 }
});
const $$=s=>[...document.querySelectorAll(s)];
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.dataset.filter==='project-query'){projectQuery=e.target.value;render();}if(e.target.dataset.filter==='task-query'){taskQuery=e.target.value;render();}});
document.addEventListener('change',async e=>{
 const el=e.target;
 if(el.dataset.toggleTask){const t=state.tasks.find(t=>t.id===el.dataset.toggleTask);toggleTask(t);save(t.status==='done'?'Satu langkah selesai. Bagus!':'Tugas dibuka kembali.');refreshTask();}
 if(el.dataset.check){const t=state.tasks.find(t=>t.id===el.dataset.parent),c=t.checklist.find(c=>c.id===el.dataset.check);c.done=el.checked;save();refreshTask();}
 if(el.dataset.taskStatus){const t=state.tasks.find(t=>t.id===el.dataset.taskStatus);t.status=el.value;save('Status tugas diperbarui.');refreshTask();}
 if(el.dataset.taskPriority){const t=state.tasks.find(t=>t.id===el.dataset.taskPriority);t.priority=el.value;save('Prioritas diperbarui.');refreshTask();}
 if(el.dataset.projectStatus){const p=state.projects.find(p=>p.id===el.dataset.projectStatus);p.status=el.value;save('Status proyek diperbarui.');render();}
 if(el.dataset.filter==='task-project'){taskProject=el.value;render();}
 if(el.id==='import-file'&&el.files[0]){const file=el.files[0];try{if(file.size>10_000_000)throw new Error('Cadangan terlalu besar. Maksimal 10 MB.');const next=validateState(JSON.parse(await file.text()));if(confirm(`Ganti workspace saat ini dengan ${next.projects.length} proyek dan ${next.tasks.length} tugas dari cadangan?`)){state=next;save('Cadangan berhasil dipulihkan.');$('#settings-dialog').close();taskProject='';go('#overview');render();}}catch(err){$('#import-error').textContent=err instanceof SyntaxError?'File ini bukan JSON yang valid.':err.message;}el.value='';}
});
document.addEventListener('submit',e=>{
 if(!['project-form','task-form','quick-check'].includes(e.target.id))return;e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f)),id=f.dataset.id;
 try{
 if(f.id==='project-form'){data.name=data.name.trim();data.description=data.description.trim();if(!data.name)throw new Error('Nama proyek perlu diisi.');let p=state.projects.find(p=>p.id===id);if(p)Object.assign(p,data);else p=createProject(state,data);save(id?'Proyek diperbarui.':'Proyek baru, kemungkinan baru.');$('#form-dialog').close();detailFilter='all';go(`#project/${p.id}`);render();}
 if(f.id==='task-form'){data.title=data.title.trim();data.notes=data.notes.trim();if(!data.title)throw new Error('Nama tugas perlu diisi.');data.checklist=[...f.querySelectorAll('.form-check')].map(row=>({id:row.dataset.checkId||uid(),text:row.querySelector('input').value.trim(),done:row.dataset.done==='true'})).filter(c=>c.text);let t=state.tasks.find(t=>t.id===id);if(t){const {status}=t;Object.assign(t,data,{status});}else t=createTask(state,data);save(id?'Tugas diperbarui.':'Tugas ditambahkan. Satu langkah lebih jelas.');$('#form-dialog').close();render();if(id)showTask(t.id);}
 if(f.id==='quick-check'){const t=state.tasks.find(t=>t.id===id),text=data.text.trim();if(!text)return;if(t.checklist.length>=100){toast('Maksimal 100 langkah per tugas.');return;}t.checklist.push({id:uid(),text,done:false});save();refreshTask();$('#quick-check input').focus();}
 }catch(err){const errEl=f.querySelector('.form-error');if(errEl)errEl.textContent=err.message;else toast(err.message);}
});
window.addEventListener('hashchange',()=>{detailFilter='all';render();window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$$('dialog[open]').length)openSearch();}});
for(const d of $$('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));render();if(openTaskId&&$('#task-dialog').open){if(state.tasks.some(t=>t.id===openTaskId))showTask(openTaskId);else $('#task-dialog').close();}toast('Workspace diperbarui dari tab lain.');}catch{toast('Perubahan dari tab lain tidak dapat dibaca.');}}});
render();
if(recovery)toast('Data browser tidak dapat dibaca. Data contoh dimuat. Pulihkan cadangan lewat menu Data.');
else save();
